AssistantMessageToolRequest(name='create', tool_call_id='function-call-854605ab-136e-4e4e-8fb5-e9cded4e8450', arguments={'file_text': "document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('contact-form');
    const fullNameInput = document.getElementById('fullName');
    const emailInput = document.getElementById('email');
    const phoneInput = document.getElementById('phone');

    // Email regex for basic validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    // Phone regex: optional + at start, then 10-15 digits
    const phoneRegex = /^\+?\d{10,15}$/;

    const setInvalid = (inputElement, errorElementId, describedByVal = '') => {
        inputElement.setAttribute('aria-invalid', 'true');
        const errorElement = document.getElementById(errorElementId);
        errorElement.removeAttribute('hidden');

        // Add error ID to aria-describedby
        let currentDescribedBy = inputElement.getAttribute('aria-describedby') || '';
        const parts = currentDescribedBy.split(' ').filter(p => p !== '');
        if (!parts.includes(errorElementId)) {
            parts.push(errorElementId);
        }
        inputElement.setAttribute('aria-describedby', parts.join(' '));
    };

    const setValid = (inputElement, errorElementId) => {
        inputElement.removeAttribute('aria-invalid');
        const errorElement = document.getElementById(errorElementId);
        errorElement.setAttribute('hidden', '');

        // Remove error ID from aria-describedby
        let currentDescribedBy = inputElement.getAttribute('aria-describedby') || '';
        const parts = currentDescribedBy.split(' ').filter(p => p !== '' && p !== errorElementId);
        if (parts.length > 0) {
            inputElement.setAttribute('aria-describedby', parts.join(' '));
        } else {
            inputElement.removeAttribute('aria-describedby');
        }
    };

    const validateForm = () => {
        let isValid = true;
        let firstInvalidElement = null;

        // Validate Full Name
        if (!fullNameInput.value.trim()) {
            setInvalid(fullNameInput, 'fullName-error');
            isValid = false;
            if (!firstInvalidElement) firstInvalidElement = fullNameInput;
        } else {
            setValid(fullNameInput, 'fullName-error');
        }

        // Validate Email
        if (!emailInput.value.trim() || !emailRegex.test(emailInput.value.trim())) {
            setInvalid(emailInput, 'email-error');
            isValid = false;
            if (!firstInvalidElement) firstInvalidElement = emailInput;
        } else {
            setValid(emailInput, 'email-error');
        }

        // Validate Phone (optional)
        const phoneVal = phoneInput.value.trim();
        // Remove non-digit/+ characters for checking? 
        // We'll just enforce the regex if provided.
        if (phoneVal !== '' && !phoneRegex.test(phoneVal.replace(/[\s\-\(\)]/g, ''))) {
            setInvalid(phoneInput, 'phone-error');
            isValid = false;
            if (!firstInvalidElement) firstInvalidElement = phoneInput;
        } else {
            setValid(phoneInput, 'phone-error');
        }

        return { isValid, firstInvalidElement };
    };

    form.addEventListener('submit', (e) => {
        e.preventDefault();
        const { isValid, firstInvalidElement } = validateForm();

        if (!isValid) {
            firstInvalidElement.focus();
        } else {
            // Success state - in a real app this would send data
            alert('Form submitted successfully!');
            form.reset();
            // Reset validation states
            [fullNameInput, emailInput, phoneInput].forEach(input => {
                const errId = input.id + '-error';
                setValid(input, errId);
            });
            // Re-add phone help text described-by if it was removed
            phoneInput.setAttribute('aria-describedby', 'phone-help');
        }
    });

    // Clear validation on input
    [fullNameInput, emailInput, phoneInput].forEach(input => {
        input.addEventListener('input', () => {
            const errId = input.id + '-error';
            if (input.hasAttribute('aria-invalid')) {
                setValid(input, errId);
            }
        });
    });

    // Initial setup for phone help text
    if (!phoneInput.getAttribute('aria-describedby')) {
        phoneInput.setAttribute('aria-describedby', 'phone-help');
    }
